export const VERSION='0.1.5';
export const DEFAULTS={labelSize:'normal',runwayExtensions:true,range:20,orientation:'track-up',projection:2,trail:60,idle:10,vertical:5000,hideVertical:false,grayVertical:true,airports:true,map:1,ownship:true,symbol:'high-wing'};
export function validateSettings(input){const s={...DEFAULTS};for(const [k,allowed] of Object.entries({range:[2,5,10,20],projection:[1,2,3,5],trail:[30,60,120,300],idle:[0,10,20,30],vertical:[2000,3000,5000,10000],map:[0,1,2]}))if(allowed.includes(Number(input?.[k])))s[k]=Number(input[k]);for(const k of ['hideVertical','grayVertical','airports','ownship','runwayExtensions'])if(typeof input?.[k]==='boolean')s[k]=input[k];if(['track-up','north-up'].includes(input?.orientation))s.orientation=input.orientation;if(['high-wing','low-wing','twin'].includes(input?.symbol))s.symbol=input.symbol;if(['normal','large','extra-large'].includes(input?.labelSize))s.labelSize=input.labelSize;return s;}
export function sample(f,t){const p=f.points;if(t<p[0][0]||t>p.at(-1)[0])return null;let lo=0,hi=p.length-1;while(hi-lo>1){const m=(lo+hi)>>1;if(p[m][0]>t)hi=m;else lo=m;}const a=p[lo],b=p[hi],k=b[0]===a[0]?0:(t-a[0])/(b[0]-a[0]);return a.slice(1).map((v,i)=>v+(b[i+1]-v)*k);}
export function ownship(t){const a=(t+600)*100/(3600*5),v=100/3600;return {e:5*Math.cos(a),n:5*Math.sin(a),alt:5000,speed:100,ve:-v*Math.sin(a),vn:v*Math.cos(a),vr:0};}
export function traffic(f,t){const p=sample(f,t);if(!p)return null;let a=sample(f,t-2),b=p,dt=2;if(!a){a=p;b=sample(f,t+2);if(!b)return null;}return {id:f.id,tail:f.tail,kind:f.kind,e:p[0],n:p[1],alt:p[2],speed:p[3],ve:(b[0]-a[0])/dt,vn:(b[1]-a[1])/dt,vr:(b[2]-a[2])/dt,flight:f};}
export function verticalClear(p,o,threshold){const d=p.alt-o.alt,end=d+(p.vr-o.vr)*300;return d*end>0&&Math.min(Math.abs(d),Math.abs(end))>threshold;}
export function closestApproach(e,n,ve,vn){const vv=ve*ve+vn*vn,t=vv<1e-12?0:Math.max(0,Math.min(300,-(e*ve+n*vn)/vv));return {time:t,distance:Math.hypot(e+ve*t,n+vn*t)};}
export function assess(p,o,s){if(!s.ownship)return {color:'#66ee9a',reason:'No ownship fix: green is display-only.',hidden:false};if(verticalClear(p,o,s.vertical)){if(s.hideVertical)return {hidden:true};if(s.grayVertical)return {color:'#81928c',reason:`Vertically separated beyond ${s.vertical.toLocaleString()} ft under the observed-rate model.`,hidden:false};}const e=p.e-o.e,n=p.n-o.n,ve=p.ve-o.ve,vn=p.vn-o.vn,cpa=closestApproach(e,n,ve,vn);if(Math.hypot(e,n)<=1&&e*ve+n*vn<0)return {color:'#ff5555',reason:'Within 1 NM and closing (horizontal).',hidden:false,cpa};if(cpa.distance<=1)return {color:'#ffda68',reason:'Projected within 1 NM in five minutes (horizontal).',hidden:false,cpa};const gap=t=>Math.hypot(e-o.ve*t,n-o.vn*t)-p.speed/3600*t;let lo=0,hi=300;for(let i=0;i<24;i++){const a=(lo*2+hi)/3,b=(lo+hi*2)/3;if(gap(a)<gap(b))hi=b;else lo=a;}if(Math.min(gap(0),gap(300),gap((lo+hi)/2))<=1)return {color:'#ffda68',reason:'A turn could bring this target within 1 NM.',hidden:false,cpa};return {color:'#66ee9a',reason:'Outside five-minute horizontal reach envelope.',hidden:false,cpa};}
export function course(p){return (Math.atan2(p.ve,p.vn)*180/Math.PI+360)%360;}
export function screenPoint(e,n,origin,heading,range){const a=heading*Math.PI/180,dx=e-origin.e,dy=n-origin.n,k=382/range;return [400+(dx*Math.cos(a)-dy*Math.sin(a))*k,400-(dx*Math.sin(a)+dy*Math.cos(a))*k];}
export function arrowPoints(point,h,direction){const side=[-h[1],h[0]].map(v=>v*(direction==='Right'?1:-1)),r=16,c=[point[0]-h[0]*26+side[0]*r,point[1]-h[1]*26+side[1]*r],p=[[point[0]+side[0]*32+h[0]*8,point[1]+side[1]*32+h[1]*8]];for(let i=0;i<=24;i++){const t=i*Math.PI/24;p.push([c[0]+r*(side[0]*Math.cos(t)-h[0]*Math.sin(t)),c[1]+r*(side[1]*Math.cos(t)-h[1]*Math.sin(t))]);}p.push([point[0]-h[0]*7,point[1]-h[1]*7]);return p;}

// Keep a tapped cluster stable while its targets continue moving.
export function nearbyTargets(hits,x,y,radius=28){return hits.map((hit,i)=>({...hit,distance:Math.hypot(hit.x-x,hit.y-y),order:i})).filter(hit=>hit.distance<=radius).sort((a,b)=>a.distance-b.distance||a.order-b.order);}

export function airportColor(a){const status=a.source?.tower;if(status==='towered')return '#48baff';if(status==='non-towered')return '#f075d5';return a.frequencies?.some(f=>f.type?.toUpperCase()==='TWR')?'#48baff':'#9aafaa';}

export function labelScale(s){return {normal:1,large:1.25,'extra-large':1.5}[s.labelSize]*{20:1,10:1.12,5:1.25,2:1.4}[s.range];}
export function runwayExtensionSegments(airport){const result=[];for(const s of airport.segments||[]){if(s.schematic||s.closed)continue;const length=Math.hypot(s.q[0]-s.p[0],s.q[1]-s.p[1]);if(length<.00001)continue;const v=[(s.q[0]-s.p[0])/length,(s.q[1]-s.p[1])/length],p=[airport.e+s.p[0],airport.n+s.p[1]],q=[airport.e+s.q[0],airport.n+s.q[1]];result.push({p,q,extensions:[[[p[0]-v[0]*3,p[1]-v[1]*3],p],[q,[q[0]+v[0]*3,q[1]+v[1]*3]]]});}return result;}
